(()=>{const legacyRender=window.render;function legacy(route){return()=>{const old=location.hash;history.replaceState(null,'','#'+route);legacyRender();if(old&&old!=='#'+route)history.replaceState(null,'',old)}}['home','search','treatments','program','hospital','consult'].forEach(r=>DemoRouter.register(r,legacy(r)));window.render=()=>DemoRouter.render();DemoRouter.start();})();